     1	import type { Customer, Item } from "./insured-item.js";
     2	
     3	const PROCESSING_FEE = 5;
     4	const CURSE_SURCHARGE_RATE = 0.5;
     5	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
     6	const HIGH_ENCHANTMENT_LEVEL = 5;
     7	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
     8	const LOYALTY_DISCOUNT_RATE = 0.2;
     9	const LOYALTY_YEARS = 2;
    10	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
    11	
    12	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
    13	  sword: 100,
    14	  amulet: 60,
    15	  staff: 80,
    16	  potion: 40,
    17	};
    18	
    19	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
    20	const COMPONENT_BASE_PREMIUM = 25;
    21	const BLOCK_SIZE = 3;
    22	const BLOCK_BASE_PREMIUM = 60;
    23	
    24	function isComponent(item: Item): boolean {
    25	  return COMPONENT_TYPES.has(item.type);
    26	}
    27	
    28	function alikeComponentGroupSizes(components: Item[]): number[] {
    29	  const sizePerType = new Map<string, number>();
    30	  for (const component of components) {
    31	    sizePerType.set(component.type, (sizePerType.get(component.type) ?? 0) + 1);
    32	  }
    33	  return [...sizePerType.values()];
    34	}
    35	
    36	// An item's own price per the MHPCO price list. A component is listed at its
    37	// individual price here; the block discount is a property of a group of alike
    38	// components, not of any single component.
    39	function itemBasePremium(item: Item): number {
    40	  return isComponent(item)
    41	    ? COMPONENT_BASE_PREMIUM
    42	    : MAIN_ITEM_BASE_PREMIUMS[item.type];
    43	}
    44	
    45	function alikeComponentGroupBasePremium(groupSize: number): number {
    46	  return groupSize === BLOCK_SIZE
    47	    ? BLOCK_BASE_PREMIUM
    48	    : groupSize * COMPONENT_BASE_PREMIUM;
    49	}
    50	
    51	function componentsBasePremium(components: Item[]): number {
    52	  return alikeComponentGroupSizes(components)
    53	    .map(alikeComponentGroupBasePremium)
    54	    .reduce((sum, premium) => sum + premium, 0);
    55	}
    56	
    57	function mainItemsBasePremium(mainItems: Item[]): number {
    58	  return mainItems
    59	    .map(itemBasePremium)
    60	    .reduce((sum, premium) => sum + premium, 0);
    61	}
    62	
    63	function policyBasePremium(items: Item[]): number {
    64	  return (
    65	    mainItemsBasePremium(items.filter((item) => !isComponent(item))) +
    66	    componentsBasePremium(items.filter(isComponent))
    67	  );
    68	}
    69	
    70	interface ItemRisk {
    71	  applies: (item: Item) => boolean;
    72	  surchargeRate: number;
    73	}
    74	
    75	const isCursed = (item: Item): boolean => item.cursed === true;
    76	
    77	const isHighlyEnchanted = (item: Item): boolean =>
    78	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
    79	
    80	const ITEM_RISKS: ItemRisk[] = [
    81	  { applies: isCursed, surchargeRate: CURSE_SURCHARGE_RATE },
    82	  { applies: isHighlyEnchanted, surchargeRate: HIGH_ENCHANTMENT_SURCHARGE_RATE },
    83	];
    84	
    85	function itemRiskSurcharge(item: Item): number {
    86	  return ITEM_RISKS.filter((risk) => risk.applies(item))
    87	    .map((risk) => itemBasePremium(item) * risk.surchargeRate)
    88	    .reduce((sum, surcharge) => sum + surcharge, 0);
    89	}
    90	
    91	function itemRiskSurcharges(items: Item[]): number {
    92	  return items
    93	    .map(itemRiskSurcharge)
    94	    .reduce((sum, surcharge) => sum + surcharge, 0);
    95	}
    96	
    97	// Every item in a quote is insured for the first time, so the initial assessment
    98	// surcharge applies to every quote -- it does not depend on the customer's history.
    99	function initialAssessmentOnEveryQuote(basePremium: number): number {
   100	  return basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
   101	}
   102	
   103	interface CustomerStanding {
   104	  yearsWithMHPCO: number;
   105	  previousContracts: number;
   106	}
   107	
   108	interface CustomerStandingDiscount {
   109	  earnedBy: (standing: CustomerStanding) => boolean;
   110	  discountRate: number;
   111	}
   112	
   113	const isLongStanding = (standing: CustomerStanding): boolean =>
   114	  standing.yearsWithMHPCO >= LOYALTY_YEARS;
   115	
   116	const isFollowUpContract = (standing: CustomerStanding): boolean =>
   117	  standing.previousContracts > 0;
   118	
   119	const CUSTOMER_STANDING_DISCOUNTS: CustomerStandingDiscount[] = [
   120	  { earnedBy: isLongStanding, discountRate: LOYALTY_DISCOUNT_RATE },
   121	  { earnedBy: isFollowUpContract, discountRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
   122	];
   123	
   124	function customerStandingDiscounts(
   125	  standing: CustomerStanding,
   126	  basePremium: number,
   127	): number {
   128	  return CUSTOMER_STANDING_DISCOUNTS.filter((discount) =>
   129	    discount.earnedBy(standing),
   130	  )
   131	    .map((discount) => basePremium * discount.discountRate)
   132	    .reduce((sum, amount) => sum + amount, 0);
   133	}
   134	
   135	function policyWideModifiers(
   136	  standing: CustomerStanding,
   137	  basePremium: number,
   138	): number {
   139	  return (
   140	    initialAssessmentOnEveryQuote(basePremium) -
   141	    customerStandingDiscounts(standing, basePremium)
   142	  );
   143	}
   144	
   145	function premiumRoundedInMhpcosFavor(premium: number): number {
   146	  return Math.ceil(premium);
   147	}
   148	
   149	export function quote(
   150	  customer: Customer,
   151	  items: Item[],
   152	  previousContracts: number,
   153	): number {
   154	  const basePremium = policyBasePremium(items);
   155	  const standing = { ...customer, previousContracts };
   156	  const premium =
   157	    basePremium +
   158	    itemRiskSurcharges(items) +
   159	    policyWideModifiers(standing, basePremium) +
   160	    PROCESSING_FEE;
   161	  return premiumRoundedInMhpcosFavor(premium);
   162	}
