     1	import type { Item } from "./insured-item.js";
     2	
     3	export interface Damage {
     4	  itemType: string;
     5	  amount: number;
     6	}
     7	
     8	export interface Incident {
     9	  cause: string;
    10	  damages: Damage[];
    11	}
    12	
    13	export interface Policy {
    14	  insuredItems: Item[];
    15	}
    16	
    17	export interface ClaimResult {
    18	  payout: number;
    19	  remainingCap: number;
    20	}
    21	
    22	const DEDUCTIBLE_PER_DAMAGE = 100;
    23	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
    24	
    25	const INSURANCE_VALUES: Record<string, number> = {
    26	  sword: 1000,
    27	  amulet: 600,
    28	  staff: 800,
    29	  potion: 400,
    30	};
    31	
    32	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
    33	const COMPONENT_INSURANCE_VALUE = 250;
    34	
    35	function insuranceValue(item: Item): number {
    36	  return COMPONENT_TYPES.has(item.type)
    37	    ? COMPONENT_INSURANCE_VALUE
    38	    : INSURANCE_VALUES[item.type];
    39	}
    40	
    41	// The MHPCO insures a policy for the sum of its items' insurance values and
    42	// pays out at most twice that sum over the policy's lifetime.
    43	function insuranceSum(policy: Policy): number {
    44	  return policy.insuredItems
    45	    .map(insuranceValue)
    46	    .reduce((sum, value) => sum + value, 0);
    47	}
    48	
    49	function payoutCap(policy: Policy): number {
    50	  return insuranceSum(policy) * CAP_MULTIPLE_OF_INSURANCE_SUM;
    51	}
    52	const HIGH_ENCHANTMENT_CLAIM_LEVEL = 8;
    53	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
    54	const FULL_REIMBURSEMENT_RATE = 1;
    55	
    56	function damagedItem(policy: Policy, damage: Damage): Item | undefined {
    57	  return policy.insuredItems.find((item) => item.type === damage.itemType);
    58	}
    59	
    60	function isHighlyEnchanted(item: Item): boolean {
    61	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_LEVEL;
    62	}
    63	
    64	// Which reimbursement clause covers the damaged item. Damage to a highly
    65	// enchanted item is reimbursed at half; all other damage in full.
    66	// The dragon-material clause is subsumed by that default: it reimburses in
    67	// full, and where it meets the high-enchantment clause the 50 % rate wins, so
    68	// it never changes a payout and needs no branch of its own.
    69	// An item the policy does not list has no clause and is reimbursed in full --
    70	// rejecting such a damage entry is a separate, not yet implemented rule.
    71	function reimbursementRateFor(item: Item | undefined): number {
    72	  if (item !== undefined && isHighlyEnchanted(item)) {
    73	    return HIGH_ENCHANTMENT_REIMBURSEMENT_RATE;
    74	  }
    75	  return FULL_REIMBURSEMENT_RATE;
    76	}
    77	
    78	// The MHPCO settles each damage event separately: it reimburses the damage
    79	// under the applicable clause, then withholds its deductible once per event.
    80	function settlementForDamageEvent(policy: Policy, damage: Damage): number {
    81	  const rate = reimbursementRateFor(damagedItem(policy, damage));
    82	  return damage.amount * rate - DEDUCTIBLE_PER_DAMAGE;
    83	}
    84	
    85	export function claim(policy: Policy, incident: Incident): ClaimResult {
    86	  const cap = payoutCap(policy);
    87	  const settled = incident.damages
    88	    .map((damage) => settlementForDamageEvent(policy, damage))
    89	    .reduce((sum, amount) => sum + amount, 0);
    90	  const payout = Math.min(settled, cap);
    91	  return { payout, remainingCap: cap - payout };
    92	}
